css:
/* The band's own geometry, measured from the handoff. It lives here rather than
   on the blog page because the parts it styles are this component's: a page that
   places the grid gets the rule with it, and renaming a node here can no longer
   leave a rule behind on a page that never mentioned it. */

/* --- Topic chips ---------------------------------------------------------
   The hairline above the chips is what separates them from the intro copy, and
   the 40px below is what stops them crowding the results header. */
[data-bz-node="pr-chips"] .bz-block { padding-block: 0; }
[data-bz-node="pr-chips-col"] { border-top: 1px solid var(--line); padding-top: 22px; }
[data-bz-node="pr-chips-row"] { margin-bottom: 40px; }
[data-bz-node="pr-chips"] .ss-filter__pills { flex-wrap: wrap; overflow: visible; padding-bottom: 0; }
[data-bz-node="pr-chips"] .ss-pill {
  border-width: 1px;
  font-size: 13px;
  letter-spacing: 0;
  text-transform: none;
  color: var(--body-text);
}
[data-bz-node="pr-chips"] .ss-pill:hover { border-color: var(--ink); color: var(--ink); }
[data-bz-node="pr-chips"] .ss-pill[aria-pressed="true"] { border-color: var(--accent); color: #fff; }

/* --- Results header ------------------------------------------------------
   Title and count sit on one baseline, the count pushed to the far edge. */
[data-bz-node="pr-head-row"] { align-items: baseline; margin-bottom: 26px; }
[data-bz-node="pr-head-row"] .bz-block { padding-block: 0; }
[data-bz-node="pr-head-h"] h2 { font-size: 30px; margin: 0; }
[data-bz-node="pr-count-col"] { text-align: right; }

/* --- Cards ---------------------------------------------------------------
   The card design is the Post cards component and its rules travel with it;
   only the block's own padding is the band's business. */
[data-bz-node="pr-cards"] .bz-block { padding-block: 0; }

@media (max-width: 640px) {
  [data-bz-node="pr-head-h"] h2 { font-size: 26px; }
  [data-bz-node="pr-head-col"], [data-bz-node="pr-count-col"] { text-align: left; }
}

/* --- Older / newer ---------------------------------------------------------
   The nav is in flow and visible before any script runs, so the canvas can
   select and reword it. The script hides it when there is only one page. */
[data-bz-node="pr-nav-row"] { margin-top: 44px; align-items: center; }
[data-bz-node="pr-nav-row"] .bz-block { padding-block: 0; }
[data-bz-node="pr-nav-row"][hidden] { display: none; }
[data-bz-node="pr-newer"] .bz-btns { justify-content: flex-start; margin-block: 0; }
[data-bz-node="pr-older"] .bz-btns { justify-content: flex-end; margin-block: 0; }
[data-bz-node="pr-nav-row"] .bz-btn { min-height: 46px; padding: 0 24px; }
[data-bz-node="pr-nav-row"] .bz-btn[aria-disabled="true"] {
  opacity: 0.35;
  pointer-events: none;
}

@media (max-width: 640px) {
  [data-bz-node="pr-newer"] .bz-btns,
  [data-bz-node="pr-older"] .bz-btns { justify-content: center; }
}

