/* Older / newer paging over the post grid.
 *
 * Not a behaviour: the eight are carousel, filter, dropdown, drawer, rotator,
 * scrollstate, dependentselect and mapsync, and none of them pages a list. The
 * band already declares `filter` for its topic chips, so this rides on top of
 * that rather than replacing it.
 *
 * The one thing to get right is whose `hidden` is whose. The filter sets
 * `item.hidden` on every card each time it applies, so a card hidden because it
 * is on page 2 is indistinguishable from one hidden because it is the wrong
 * topic — unless the matched set is read at the one moment it is trustworthy,
 * which is immediately after the filter has run and before this touches
 * anything. That is what `bz:filter` marks, and what `matched` below holds. */
(function () {
  var PER_PAGE = 12; /* the design's four across, three rows down */

  function setup(band) {
    var grid = band.querySelector('[data-bz-part="item"]');
    if (!grid) return;
    var items = Array.prototype.slice.call(band.querySelectorAll('[data-bz-part="item"]'));
    var newer = band.querySelector('[data-bz-node^="pr-newer"] .bz-btn');
    var older = band.querySelector('[data-bz-node^="pr-older"] .bz-btn');
    if (!newer || !older || !items.length) return;

    var matched = items.slice();
    var page = 0;

    function pages() {
      return Math.max(1, Math.ceil(matched.length / PER_PAGE));
    }

    function draw() {
      var start = page * PER_PAGE;
      matched.forEach(function (item, i) {
        item.hidden = i < start || i >= start + PER_PAGE;
      });
      /* An anchor cannot be `disabled`, so the state is announced rather than
         implied, and the CSS greys it from the same attribute. */
      arrive(newer, page > 0);
      arrive(older, page < pages() - 1);
      /* Nothing to page through is nothing to show: one page of results should
         not carry a nav that does nothing. */
      var nav = band.querySelector('[data-bz-node="pr-nav-row"]');
      if (nav) nav.hidden = matched.length <= PER_PAGE;
    }

    function arrive(link, on) {
      link.setAttribute('aria-disabled', String(!on));
      link.tabIndex = on ? 0 : -1;
    }

    function go(delta, event) {
      event.preventDefault();
      var next = Math.min(pages() - 1, Math.max(0, page + delta));
      if (next === page) return;
      page = next;
      draw();
      band.scrollIntoView({
        behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth',
        block: 'start',
      });
    }

    newer.addEventListener('click', function (e) { go(-1, e); });
    older.addEventListener('click', function (e) { go(1, e); });

    /* The filter runs its first pass while widgets.js loads, which is before
       this script exists — so the opening state is read here rather than waited
       for, and only later changes arrive as events. */
    function resync() {
      matched = items.filter(function (item) { return !item.hidden; });
      page = 0;
      draw();
    }
    resync();
    band.addEventListener('bz:filter', resync);
  }

  var bands = document.querySelectorAll('[data-bz-section="post-rail"]');
  Array.prototype.forEach.call(bands, setup);
})();
